/// @file Codec.h
/// @brief 消息编解码器 —— 自定义二进制协议
///
/// 协议格式（Length-Value）：
///   +--------------------+--------------------+
///   | Length (4 bytes BE) | JSON payload       |
///   +--------------------+--------------------+
///   |<------ network byte order ----------->|
///
/// JSON payload 字段说明：
///   {
///     "type" : "chat" | "join" | "leave" | "kick" | "sys",
///     "from" : "用户名",
///     "to"   : "目标用户" (可选，为空则广播),
///     "body" : "消息内容",
///     "ts"   : 1690000000  (unix timestamp, 秒)
///   }

#include <muduo/net/TcpConnection.h>
#include <muduo/net/Buffer.h>
#include <nlohmann/json.hpp>

#include <cstdint>
#include <functional>
#include <string>

/// @brief 消息类型枚举
enum class MsgType : uint8_t {
    kChat   = 0,   // 普通聊天
    kJoin   = 1,   // 用户加入
    kLeave  = 2,   // 用户离开
    kKick   = 3,   // 踢人
    kSys    = 4,   // 系统通知
};

/// @brief 把 MsgType 转为 JSON 字符串
const char* msgTypeToString(MsgType t);

/// @brief 把 JSON 字符串转为 MsgType
MsgType stringToMsgType(const std::string& s);

/// @brief 网络层消息包
struct Message {
    MsgType    type;
    std::string from;      // 发送者
    std::string to;        // 接收者（空 = 广播）
    std::string body;      // 消息正文
    int64_t     timestamp; // unix 时间戳

    /// 序列化为 JSON 字符串
    std::string toJson() const;

    /// 从 JSON 字符串反序列化
    static Message fromJson(const std::string& jsonStr);
};

/// @brief TLV 编解码器
///
/// 负责：
///   1. 把 Message 编码为 Length-Value 二进制帧
///   2. 从 TCP 流中解码出完整的 Message
class Codec {
public:
    /// 回调类型：解码出一条完整消息后触发
    using MessageCallback = std::function<void(
        const muduo::net::TcpConnectionPtr&,
        const Message&)>;

    explicit Codec(MessageCallback cb) : callback_(std::move(cb)) {}

    /// 编码：Message → 二进制帧（4字节长度头 + JSON）
    static std::string encode(const Message& msg);

    /// 解码：从 Buffer 中读取所有完整帧
    void onMessage(const muduo::net::TcpConnectionPtr& conn,
                   muduo::net::Buffer* buf);

private:
    MessageCallback callback_;
};
"}

