/// @file ChatServer.h
/// @brief 聊天服务器核心类
///
/// 职责：
///   1. 接受客户端 TCP 连接（使用 muduo TcpServer）
///   2. 维护在线用户表（线程安全）
///   3. 根据消息类型分发处理
///   4. 广播消息给所有在线客户端

#include "Codec.h"
#include <muduo/net/TcpServer.h>
#include <muduo/net/EventLoop.h>
#include <muduo/net/InetAddress.h>

#include <atomic>
#include <memory>
#include <mutex>
#include <string>
#include <unordered_map>

/// @brief 每个在线用户的连接上下文
struct UserContext {
    std::string username;                   // 用户名
    muduo::net::TcpConnectionPtr conn;      // TCP 连接
    int64_t login_time;                     // 登录时间
};

/// @brief 聊天服务器
class ChatServer {
public:
    /// @param loop       事件循环
    /// @param listenAddr 监听地址
    ChatServer(muduo::net::EventLoop* loop,
               const muduo::net::InetAddress& listenAddr);

    /// 启动服务器
    void start();

    /// 获取在线用户数（线程安全）
    size_t onlineCount() const;

private:
    // -------- muduo 回调 --------
    void onConnection(const muduo::net::TcpConnectionPtr& conn);
    void onMessageDecoded(const muduo::net::TcpConnectionPtr& conn,
                          const Message& msg);

    // -------- 消息处理 --------
    void handleJoin(const muduo::net::TcpConnectionPtr& conn,
                    const Message& msg);
    void handleChat(const muduo::net::TcpConnectionPtr& conn,
                    const Message& msg);
    void handleLeave(const muduo::net::TcpConnectionPtr& conn);

    // -------- 广播 --------
    void broadcast(const Message& msg);
    void broadcastExcept(const Message& msg,
                         const muduo::net::TcpConnectionPtr& exclude);

    // -------- 工具 --------
    void sendTo(const muduo::net::TcpConnectionPtr& conn,
                const Message& msg);
    void sendSystemMessage(const muduo::net::TcpConnectionPtr& conn,
                           const std::string& body);
    std::string generateUsername(const muduo::net::TcpConnectionPtr& conn);
    int64_t now() const;

    muduo::net::TcpServer  server_;       // TCP 服务器
    Codec                   codec_;       // 编解码器

    mutable std::mutex      mutex_;       // 保护 users_
    std::unordered_map<std::string, UserContext> users_;   // conn name → 用户上下文
    std::atomic<int>        user_counter_{0};              // 用户编号
};
"}

{"file_path": "chat_server/src/Codec.cpp", "old_string": "", "new_string": "/// @file Codec.cpp
/// @brief 消息编解码器实现

#include "Codec.h"
#include <muduo/base/Logging.h>
#include <cstring>
#include <stdexcept>

// ========== MsgType 枚举工具 ==========

const char* msgTypeToString(MsgType t) {
    switch (t) {
        case MsgType::kChat:  return "chat";
        case MsgType::kJoin:  return "join";
        case MsgType::kLeave: return "leave";
        case MsgType::kKick:  return "kick";
        case MsgType::kSys:   return "sys";
        default:              return "unknown";
    }
}

MsgType stringToMsgType(const std::string& s) {
    if (s == "chat")  return MsgType::kChat;
    if (s == "join")  return MsgType::kJoin;
    if (s == "leave") return MsgType::kLeave;
    if (s == "kick")  return MsgType::kKick;
    if (s == "sys")   return MsgType::kSys;
    return MsgType::kSys;
}

// ========== Message 序列化 / 反序列化 ==========

std::string Message::toJson() const {
    nlohmann::json j;
    j["type"] = msgTypeToString(type);
    j["from"] = from;
    j["to"]   = to;
    j["body"] = body;
    j["ts"]   = timestamp;
    return j.dump();  // compact JSON
}

Message Message::fromJson(const std::string& jsonStr) {
    try {
        auto j = nlohmann::json::parse(jsonStr);
        Message msg;
        msg.type      = stringToMsgType(j.value("type", "sys"));
        msg.from      = j.value("from", "");
        msg.to        = j.value("to",   "");
        msg.body      = j.value("body", "");
        msg.timestamp = j.value("ts",   0LL);
        return msg;
    } catch (const std::exception& e) {
        LOG_ERROR << "Message::fromJson failed: " << e.what()
                  << " raw=" << jsonStr;
        throw;
    }
}

// ========== Codec 编码 / 解码 ==========

/// 编码：4字节大端长度头 + JSON payload
std::string Codec::encode(const Message& msg) {
    std::string payload = msg.toJson();
    uint32_t len = static_cast<uint32_t>(payload.size());

    // 构造 4 字节大端长度头
    char header[4];
    header[0] = static_cast<char>((len >> 24) & 0xFF);
    header[1] = static_cast<char>((len >> 16) & 0xFF);
    header[2] = static_cast<char>((len >>  8) & 0xFF);
    header[3] = static_cast<char>((len      ) & 0xFF);

    std::string frame;
    frame.reserve(4 + len);
    frame.append(header, 4);
    frame.append(payload);
    return frame;
}

/// 解码：从 Buffer 中循环读取所有完整消息
void Codec::onMessage(const muduo::net::TcpConnectionPtr& conn,
                      muduo::net::Buffer* buf)
{
    // 循环：只要 buffer 中有完整的一帧就继续解析
    while (buf->readableBytes() >= 4) {
        // 读取 4 字节大端长度头（peek，不消费）
        const char* data = buf->peek();
        uint32_t payloadLen = (static_cast<uint8_t>(data[0]) << 24)
                            | (static_cast<uint8_t>(data[1]) << 16)
                            | (static_cast<uint8_t>(data[2]) <<  8)
                            | (static_cast<uint8_t>(data[3]));

        // 防止恶意超大包（限制 64KB）
        if (payloadLen > 65536) {
            LOG_ERROR << "payload too large: " << payloadLen
                      << " from " << conn->name();
            conn->shutdown();
            return;
        }

        // 检查数据是否已经到达
        if (buf->readableBytes() < 4 + payloadLen) {
            break;  // 等待更多数据
        }

        // 消费 length header
        buf->retrieve(4);

        // 提取 JSON payload
        std::string payload(buf->peek(), payloadLen);
        buf->retrieve(payloadLen);

        // 反序列化
        try {
            Message msg = Message::fromJson(payload);
            if (callback_) {
                callback_(conn, msg);
            }
        } catch (const std::exception& e) {
            LOG_ERROR << "decode failed from " << conn->name()
                      << ": " << e.what();
        }
    }
}
"}

