/// @brief 聊天服务器核心实现

#include "ChatServer.h"
#include <muduo/base/Logging.h>
#include <chrono>
#include <sstream>

// ========== 构造 / 启动 ==========

ChatServer::ChatServer(muduo::net::EventLoop* loop,
                       const muduo::net::InetAddress& listenAddr)
    : server_(loop, listenAddr, "ChatServer"),
      codec_(std::bind(&ChatServer::onMessageDecoded, this,
                        std::placeholders::_1,
                        std::placeholders::_2))
{
    // 注册 muduo 回调
    server_.setConnectionCallback(
        std::bind(&ChatServer::onConnection, this, std::placeholders::_1));
    server_.setMessageCallback(
        std::bind(&Codec::onMessage, &codec_,
                  std::placeholders::_1,
                  std::placeholders::_2));

    // 设置 4 个 IO 线程（高并发）
    server_.setThreadNum(4);

    LOG_INFO << "ChatServer constructed, listening on "
             << listenAddr.toIpPort();
}

void ChatServer::start() {
    server_.start();
    LOG_INFO << "ChatServer started";
}

size_t ChatServer::onlineCount() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return users_.size();
}

// ========== 连接回调 ==========

void ChatServer::onConnection(const muduo::net::TcpConnectionPtr& conn) {
    LOG_INFO << "ChatServer - " << conn->peerAddress().toIpPort()
             << " is " << (conn->connected() ? "UP" : "DOWN");

    if (conn->connected()) {
        // 新连接：生成用户名
        std::string username = generateUsername(conn);
        UserContext ctx;
        ctx.username   = username;
        ctx.conn       = conn;
        ctx.login_time = now();

        {
            std::lock_guard<std::mutex> lock(mutex_);
            users_[conn->name()] = ctx;
        }

        // 在连接上设置用户名（方便后续查找）
        conn->setContext(username);

        // 发送欢迎消息
        sendSystemMessage(conn,
            "欢迎加入聊天室! 你的昵称是: " + username);

        // 广播加入通知
        Message joinMsg;
        joinMsg.type      = MsgType::kJoin;
        joinMsg.from      = username;
        joinMsg.body      = username + " 加入了聊天室";
        joinMsg.timestamp = now();
        broadcastExcept(joinMsg, conn);

        // 发送在线人数
        sendSystemMessage(conn,
            "当前在线人数: " + std::to_string(onlineCount()));
    } else {
        // 连接断开
        handleLeave(conn);
    }
}

// ========== 消息分发 ==========

void ChatServer::onMessageDecoded(const muduo::net::TcpConnectionPtr& conn,
                                   const Message& msg)
{
    LOG_INFO << "[" << msg.from << "] type=" << msgTypeToString(msg.type)
             << " body=" << msg.body;

    switch (msg.type) {
        case MsgType::kChat:
            handleChat(conn, msg);
            break;
        case MsgType::kJoin:
            // Join 已在 onConnection 中处理
            break;
        case MsgType::kLeave:
            handleLeave(conn);
            break;
        case MsgType::kKick:
            // 简易实现：不处理踢人
            sendSystemMessage(conn, "踢人功能暂未实现");
            break;
        case MsgType::kSys:
            // 系统消息，不处理
            break;
        default:
            LOG_WARN << "unknown message type from " << conn->name();
    }
}

// ========== 聊天消息处理 ==========

void ChatServer::handleChat(const muduo::net::TcpConnectionPtr& conn,
                             const Message& msg)
{
    Message outMsg;
    outMsg.type      = MsgType::kChat;
    outMsg.from      = msg.from;
    outMsg.body      = msg.body;
    outMsg.timestamp = now();

    if (msg.to.empty()) {
        // 广播给所有人
        broadcast(outMsg);
    } else {
        // 私聊：查找目标用户
        std::lock_guard<std::mutex> lock(mutex_);
        for (auto& [name, ctx] : users_) {
            if (ctx.username == msg.to) {
                sendTo(ctx.conn, outMsg);
                // 同时发送给发送者（回显）
                sendTo(conn, outMsg);
                return;
            }
        }
        // 目标不存在
        sendSystemMessage(conn, "用户 " + msg.to + " 不在线");
    }
}

// ========== 用户离开处理 ==========

void ChatServer::handleLeave(const muduo::net::TcpConnectionPtr& conn) {
    std::string username;
    {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = users_.find(conn->name());
        if (it != users_.end()) {
            username = it->second.username;
            users_.erase(it);
        }
    }

    if (!username.empty()) {
        // 广播离开通知
        Message leaveMsg;
        leaveMsg.type      = MsgType::kLeave;
        leaveMsg.from      = username;
        leaveMsg.body      = username + " 离开了聊天室";
        leaveMsg.timestamp = now();
        broadcast(leaveMsg);

        LOG_INFO << username << " left the chat room, online="
                 << onlineCount();
    }
}

// ========== 广播 ==========

void ChatServer::broadcast(const Message& msg) {
    std::string frame = Codec::encode(msg);
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& [name, ctx] : users_) {
        ctx.conn->send(frame);
    }
}

void ChatServer::broadcastExcept(const Message& msg,
                                  const muduo::net::TcpConnectionPtr& exclude)
{
    std::string frame = Codec::encode(msg);
    std::lock_guard<std::mutex> lock(mutex_);
    for (auto& [name, ctx] : users_) {
        if (ctx.conn != exclude) {
            ctx.conn->send(frame);
        }
    }
}

// ========== 工具函数 ==========

void ChatServer::sendTo(const muduo::net::TcpConnectionPtr& conn,
                         const Message& msg)
{
    conn->send(Codec::encode(msg));
}

void ChatServer::sendSystemMessage(const muduo::net::TcpConnectionPtr& conn,
                                    const std::string& body)
{
    Message msg;
    msg.type      = MsgType::kSys;
    msg.from      = "系统";
    msg.body      = body;
    msg.timestamp = now();
    sendTo(conn, msg);
}

std::string ChatServer::generateUsername(const muduo::net::TcpConnectionPtr& conn) {
    int id = user_counter_.fetch_add(1) + 1;
    std::ostringstream oss;
    oss << "用户" << id;
    return oss.str();
}

int64_t ChatServer::now() const {
    return std::chrono::duration_cast<std::chrono::seconds>(
        std::chrono::system_clock::now().time_since_epoch()
    ).count();
}
"}

{"file_path": "chat_server/src/main.cpp", "new_string": "/// @file main.cpp
/// @brief 聊天服务器入口

#include "ChatServer.h"
#include <muduo/base/Logging.h>
#include <muduo/net/EventLoop.h>
#include <muduo/net/InetAddress.h>

#include <cstdio>
#include <cstdlib>
#include <signal.h>

/// 全局事件循环指针（用于信号处理）
static muduo::net::EventLoop* g_loop = nullptr;

static void signalHandler(int sig) {
    LOG_INFO << "Caught signal " << sig << ", shutting down...";
    if (g_loop) {
        g_loop->quit();
    }
}

int main(int argc, char* argv[]) {
    uint16_t port = 9981;  // 默认端口
    if (argc >= 2) {
        port = static_cast<uint16_t>(std::atoi(argv[1]));
    }

    LOG_INFO << "Chat server starting on port " << port;

    // 设置信号处理
    signal(SIGINT,  signalHandler);
    signal(SIGTERM, signalHandler);
    signal(SIGPIPE, SIG_IGN);  // 忽略 SIGPIPE，防止 send() 崩溃

    muduo::net::EventLoop loop;
    g_loop = &loop;

    muduo::net::InetAddress listenAddr(port);
    ChatServer server(&loop, listenAddr);

    server.start();
    loop.loop();  // 事件循环（阻塞）

    LOG_INFO << "Chat server stopped";
    return 0;
}
"}

{"file_path": "chat_server/client/ChatClient.cpp", "new_string": "/// @file ChatClient.cpp
/// @brief 命令行聊天客户端
///
/// 用法：./chat_client [host] [port]
/// 默认连接 127.0.0.1:9981
///
/// 支持命令：
///   /quit        - 退出
///   /w <user>    - 私聊
///   其他         - 广播

#include "Codec.h"
#include <muduo/base/Logging.h>
#include <muduo/net/TcpClient.h>
#include <muduo/net/EventLoop.h>
#include <muduo/net/InetAddress.h>

#include <iostream>
#include <string>
#include <thread>
#include <atomic>

using namespace muduo::net;

class ChatClient {
public:
    ChatClient(EventLoop* loop, const InetAddress& serverAddr)
        : loop_(loop),
          client_(loop, serverAddr, "ChatClient"),
          codec_(std::bind(&ChatClient::onMessage, this,
                            std::placeholders::_1,
                            std::placeholders::_2)),
          running_(false)
    {
        client_.setConnectionCallback(
            std::bind(&ChatClient::onConnection, this, std::placeholders::_1));
        client_.setMessageCallback(
            std::bind(&Codec::onMessage, &codec_,
                      std::placeholders::_1,
                      std::placeholders::_2));
    }

    void start() {
        client_.connect();
    }

    void stop() {
        running_ = false;
        if (auto conn = conn_.lock()) {
            conn->shutdown();
        }
        loop_->quit();
    }

    void send(const std:: string& text) {
        auto conn = conn_.lock();
        if (!conn) {
            std::cout << "[错误] 未连接到服务器" << std::endl;
            return;
        }

        Message msg;
        msg.type      = MsgType::kChat;
        msg.from      = username_;
        msg.body      = text;
        msg.timestamp = std::time(nullptr);

        // 处理私聊命令
        if (text.substr(0, 3) == "/w ") {
            auto spacePos = text.find(' ', 3);
            if (spacePos != std::string::npos) {
                msg.to   = text.substr(3, spacePos - 3);
                msg.body = text.substr(spacePos + 1);
            }
        }

        conn->send(Codec::encode(msg));
    }

private:
    void onConnection(const TcpConnectionPtr& conn) {
        if (conn->connected()) {
            conn_ = conn;
            running_ = true;
            std::cout << "\n[连接成功] " << conn->peerAddress().toIpPort()
                      << std::endl;
            std::cout << "输入消息回车发送，/w <用户> <消息> 私聊，/quit 退出\n"
                      << std::endl;
        } else {
            running_ = false;
            std::cout << "\n[连接断开]" << std::endl;
            loop_->quit();
        }
    }

    void onMessage(const TcpConnectionPtr& /*conn*/, const Message& msg) {
        switch (msg.type) {
            case MsgType::kChat:
                std::cout << "[" << msg.from << "]: " << msg.body << std::endl;
                break;
            case MsgType::kJoin:
            case MsgType::kLeave:
                std::cout << ">> " << msg.body << std::endl;
                break;
            case MsgType::kSys:
                // 系统消息中提取用户名
                if (username_.empty() &&
                    msg.body.find("你的昵称是:") != std::string::npos)
                {
                    auto pos = msg.body.find("你的昵称是: ");
                    if (pos != std::string::npos) {
                        username_ = msg.body.substr(pos + 7);
                    }
                }
                std::cout << "[系统] " << msg.body << std::endl;
                break;
            default:
                break;
        }
    }

    EventLoop*              loop_;
    TcpClient               client_;
    Codec                   codec_;
    std::weak_ptr<TcpConnection> conn_;
    std::string             username_;
    std::atomic<bool>       running_;
};

// ========== 标准输入线程 ==========
static void inputThread(ChatClient* client, std::atomic<bool>* running) {
    std::string line;
    while (*running) {
        if (!std::getline(std::cin, line)) {
            break;
        }
        if (line == "/quit") {
            client->stop();
            break;
        }
        if (!line.empty()) {
            client->send(line);
        }
    }
}

int main(int argc, char* argv[]) {
    const char* host = "127.0.0.1";
    uint16_t    port = 9981;

    if (argc >= 2) host = argv[1];
    if (argc >= 3) port = static_cast<uint16_t>(std::atoi(argv[2]));

    std::cout << "正在连接 " << host << ":" << port << " ..." << std::endl;

    EventLoop loop;
    InetAddress serverAddr(host, port);
    ChatClient client(&loop, serverAddr);

    // 启动输入线程
    std::atomic<bool> running{true};
    std::thread input(inputThread, &client, &running);

    client.start();
    loop.loop();  // 阻塞

    running = false;
    if (input.joinable()) {
        input.join();
    }

    std::cout << "客户端退出" << std::endl;
    return 0;
}
"}
